<?php require '../config.php';require '../includes/functions.php';if(isset($_POST['login'])){verify_csrf();$q=$pdo->prepare('SELECT * FROM admin WHERE email=?');$q->execute([$_POST['email']]);$a=$q->fetch();$valid=$a&&(password_verify($_POST['password'],$a['password'])||($a['password']==='admin123'&&hash_equals('admin123',$_POST['password'])));if($valid){if($a['password']==='admin123')$pdo->prepare('UPDATE admin SET password=? WHERE id=?')->execute([password_hash('admin123',PASSWORD_DEFAULT),$a['id']]);$_SESSION['admin']=['id'=>$a['id'],'name'=>$a['name']];header('Location: index.php');exit;}$err='Invalid admin credentials.';}if(isset($_GET['logout'])){unset($_SESSION['admin']);header('Location: index.php');exit;}if(!admin_in()):?><!doctype html><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><div class="container py-5"><div class="card mx-auto p-4 shadow-sm" style="max-width:420px"><h2>NovaCart Admin</h2><?php if(isset($err)):?><div class="alert alert-danger"><?=$err?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input class="form-control mb-2" type="email" name="email" placeholder="Email" required><input class="form-control mb-3" type="password" name="password" placeholder="Password" required><button name="login" class="btn btn-primary w-100">Sign in</button></form><small class="text-muted d-block mt-3">admin@gmail.com / admin123</small></div></div><?php exit;endif;$action=$_GET['action']??'dashboard';if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save_product'])){verify_csrf();$image='images/products/'.basename($_POST['image']??'iphone.svg');$q=$pdo->prepare('INSERT INTO products(name,category_id,price,discount_price,stock,description,image,rating) VALUES(?,?,?,?,?,?,?,4.5)');$q->execute([trim($_POST['name']),$_POST['category_id'],$_POST['price'],$_POST['discount_price']?:null,$_POST['stock'],trim($_POST['description']),$image]);$_SESSION['flash']='Product added.';header('Location:index.php?action=products');exit;}if(isset($_GET['delete_product'])){$pdo->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_GET['delete_product']]);header('Location:index.php?action=products');exit;}$stats=['Users'=>$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn(),'Products'=>$pdo->query('SELECT COUNT(*) FROM products')->fetchColumn(),'Orders'=>$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn(),'Sales'=>money($pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status!='Cancelled'")->fetchColumn())];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin | NovaCart</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../css/style.css" rel="stylesheet"></head><body><nav class="navbar navbar-dark"><div class="container"><b class="navbar-brand">NOVA<span>CART</span> ADMIN</b><a class="btn btn-sm btn-light" href="?logout=1">Logout</a></div></nav><div class="container py-4"><div class="d-flex gap-2 mb-4"><a class="btn btn-outline-primary" href="index.php">Dashboard</a><a class="btn btn-outline-primary" href="?action=products">Products</a><a class="btn btn-outline-primary" href="?action=orders">Orders</a></div><?php if($action==='products'):$cats=$pdo->query('SELECT * FROM categories')->fetchAll();$ps=products($pdo);?><h2>Product management</h2><div class="card p-3 mb-4"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="col-md-3"><input required class="form-control" name="name" placeholder="Product name"></div><div class="col-md-2"><select class="form-select" name="category_id"><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input required class="form-control" name="price" placeholder="Price"></div><div class="col-md-2"><input class="form-control" name="discount_price" placeholder="Sale price"></div><div class="col-md-1"><input required class="form-control" name="stock" placeholder="Stock"></div><div class="col-md-2"><input class="form-control" name="image" placeholder="iphone.svg"></div><div class="col-10"><input class="form-control" name="description" placeholder="Description"></div><div class="col-2"><button name="save_product" class="btn btn-primary w-100">Add product</button></div></form></div><table class="table"><thead><tr><th>Name</th><th>Price</th><th>Stock</th><th></th></tr></thead><?php foreach($ps as $p):?><tr><td><?=e($p['name'])?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><a onclick="return confirm('Delete this product?')" class="btn btn-sm btn-danger" href="?action=products&delete_product=<?=$p['id']?>">Delete</a></td></tr><?php endforeach;?></table><?php elseif($action==='orders'):$os=$pdo->query('SELECT o.*,u.name FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC')->fetchAll();?><h2>Order management</h2><table class="table"><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th></tr><?php foreach($os as $o):?><tr><td><?=e($o['order_no'])?></td><td><?=e($o['name'])?></td><td><?=money($o['total'])?></td><td><?=e($o['status'])?></td></tr><?php endforeach;?></table><?php else:?><h1>Dashboard</h1><div class="row g-3"><?php foreach($stats as $k=>$v):?><div class="col-md-3"><div class="admin-stat p-4"><small><?=$k?></small><h2><?=$v?></h2></div></div><?php endforeach;?></div><div class="card p-4 mt-4"><h5>Revenue overview</h5><canvas id="chart"></canvas></div><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>new Chart(document.getElementById('chart'),{type:'line',data:{labels:['Jan','Feb','Mar','Apr','May','Jun'],datasets:[{label:'Revenue',data:[12000,19000,14500,23000,21000,28000],borderColor:'#5b4bdb',tension:.4}]}})</script><?php endif;?></div></body></html>
